import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
import base64

def validate_document_fields(payload, config=None):
    config = config or {}
    endpoint = config.get('endpoint') or os.getenv('AZURE_DOCUMENTINTELLIGENCE_ENDPOINT')
    api_key = config.get('api_key') or os.getenv('AZURE_DOCUMENTINTELLIGENCE_KEY')
    if not endpoint or not api_key:
        raise ValueError('Azure Document Intelligence endpoint and api_key are required in config or environment variables.')
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    model_id = config.get('model_id', 'prebuilt-invoice')
    required_fields = config.get('required_fields', ['InvoiceId', 'InvoiceTotal'])
    confidence_threshold = config.get('confidence_threshold', 0.7)
    if isinstance(payload, dict) and 'base64' in payload:
        analyze_request = {'base64Source': payload['base64']}
    elif isinstance(payload, str):
        analyze_request = {'base64Source': payload}
    elif isinstance(payload, bytes):
        analyze_request = {'base64Source': base64.b64encode(payload).decode('utf-8')}
    else:
        raise ValueError("Payload must contain 'base64' key (str), be base64 str, or bytes.")
    poller = client.begin_analyze_document(model_id=model_id, document=analyze_request)
    result_doc = poller.result()
    fields_status = {field: False for field in required_fields}
    extracted_fields = {}
    if result_doc.documents:
        doc = result_doc.documents[0]
        for field_name, field in doc.fields.items():
            value = field.content
            confidence = field.confidence
            extracted_fields[field_name] = {
                'value': value,
                'confidence': confidence
            }
            if field_name in fields_status:
                fields_status[field_name] = confidence >= confidence_threshold if confidence is not None else False
    is_valid = all(fields_status.values())
    result = {
        'valid': is_valid,
        'fields_status': fields_status,
        'extracted_fields': extracted_fields
    }
    return result
